import{_ as e,o as r,c as t,a4 as n}from"./chunks/framework.cM03Lg2X.js";const f=JSON.parse('{"title":"模型、数据与应用","description":"Transformer、MoE、创新架构、多模态、数据工程与 Agent/RAG 应用总结。","frontmatter":{"title":"模型、数据与应用","description":"Transformer、MoE、创新架构、多模态、数据工程与 Agent/RAG 应用总结。"},"headers":[],"relativePath":"ai-infra/models-data-apps.md","filePath":"ai-infra/models-data-apps.md","lastUpdated":1786332289000}'),o={name:"ai-infra/models-data-apps.md"};function l(i,a,s,p,d,h){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="模型、数据与应用" tabindex="-1">模型、数据与应用 <a class="header-anchor" href="#模型、数据与应用" aria-label="Permalink to “模型、数据与应用”">​</a></h1><p>模型架构决定计算形态，数据决定模型看到的世界，应用系统决定能力如何被约束和验证。三者需要与 Infra 一起设计：架构变化会改变通信和缓存，数据流程会改变训练成本，应用目标会反向决定评估方式。</p><h2 id="模型架构的三条演进线" tabindex="-1">模型架构的三条演进线 <a class="header-anchor" href="#模型架构的三条演进线" aria-label="Permalink to “模型架构的三条演进线”">​</a></h2><ol><li><strong>Transformer 内部优化</strong>：从多头注意力到 MQA、GQA、MLA，主要在能力、KV Cache 与计算开销间权衡。</li><li><strong>稀疏化扩展</strong>：MoE 用路由激活少量专家，在不同比例的参数量和计算量之间解耦，但引入负载均衡和专家通信问题。</li><li><strong>替代或混合架构</strong>：RWKV、SSM/Mamba、RetNet 等尝试降低长序列复杂度；它们更可能与注意力形成混合系统，而不是简单“一代替一代”。</li></ol><h2 id="数据工程比-收集更多-更复杂" tabindex="-1">数据工程比“收集更多”更复杂 <a class="header-anchor" href="#数据工程比-收集更多-更复杂" aria-label="Permalink to “数据工程比“收集更多”更复杂”">​</a></h2><p>高质量数据管线至少包括来源管理、提取、格式化、安全过滤、去重、质量验证与版本追踪。预训练强调规模、覆盖与分布，后训练强调任务定义、反馈质量和边界样本。</p><p>一个可复用判断是：</p><blockquote><p>数据质量通常比后训练数据数量更重要，但“质量”必须由目标任务、评估方法和可追溯来源共同定义。</p></blockquote><p>合成数据可以扩展任务覆盖，却可能放大教师模型偏差；数据蒸馏能降低成本，却需要检查能力上限和分布坍缩。数据飞轮成立的前提是线上反馈真实、可用且不会把错误重新注入训练集。</p><h2 id="多模态不是简单拼接模态" tabindex="-1">多模态不是简单拼接模态 <a class="header-anchor" href="#多模态不是简单拼接模态" aria-label="Permalink to “多模态不是简单拼接模态”">​</a></h2><p>CLIP 建立跨模态对齐，DALL·E / Stable Diffusion 负责生成，BLIP 系列连接理解与生成。工程上需要明确每个模块的训练目标、表征接口和评估口径，否则“支持多模态”只会成为模糊标签。</p><h2 id="应用层-agent、rag-与协议" tabindex="-1">应用层：Agent、RAG 与协议 <a class="header-anchor" href="#应用层-agent、rag-与协议" aria-label="Permalink to “应用层：Agent、RAG 与协议”">​</a></h2><ul><li><strong>Agent</strong> 把模型置于规划、工具调用、环境反馈和状态管理的循环中。</li><li><strong>RAG</strong> 用检索补充动态或私域知识，价值在可更新、可引用和可控制，不只是让回答更长。</li><li><strong>MCP / A2A</strong> 分别关注模型连接工具与 Agent 间协作，但协议只能解决接口互操作，不能替代权限、安全与结果验证。</li></ul><p>应用设计应先回答三个问题：模型何时需要外部信息、工具结果怎样验证、失败时系统如何回退。Qwen3 RAG、RAGFlow 等案例说明检索质量、切分、重排和引用仍是系统效果的关键。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://app.notion.com/p/06-33b3a54bd6b481599537e42346c6ca51" target="_blank" rel="noreferrer">Notion：06 大模型算法与数据</a></li><li><a href="https://app.notion.com/p/07-33b3a54bd6b481a7827cd6068cf22c72" target="_blank" rel="noreferrer">Notion：07 大模型应用</a></li></ul>',16)])])}const g=e(o,[["render",l]]);export{f as __pageData,g as default};
